const icon={home:'⌂',practice:'✧',journal:'▤',growth:'◷',settings:'⚙',back:'‹',more:'···'};
const btn=(text,target,cls='primary')=>`<button class="${cls}" ${target?`data-go="${target}"`:''}>${text}</button>`;
const pill=(text,selected=false)=>`<button class="pill ${selected?'selected':''}" data-select>${text}</button>`;
const pills=(items,active=0)=>`<div class="pills">${items.map((x,i)=>pill(x,i===active)).join('')}</div>`;
const segments=(items,active=0)=>`<div class="segments">${items.map((x,i)=>`<button data-select class="${i===active?'selected':''}">${x}</button>`).join('')}</div>`;
const heading=(title,link='',go='')=>`<div class="section-heading"><h4>${title}</h4>${link?btn(link,go,'text-btn'):''}</div>`;
const card=(body,cls='')=>`<div class="card ${cls}">${body}</div>`;
const item=(symbol,title,sub,go='',tail='›')=>`<div class="list-item"><span class="badge">${symbol}</span><div class="detail"><strong>${title}</strong><small>${sub}</small></div>${btn(tail,go,'circle')}</div>`;
const primary=(label,target)=>btn(label+' <span>↗</span>',target);
const info=(label,desc,go='35')=>card(`<div class="kicker">A MOMENT TO UNDERSTAND</div><h4>${label}</h4><p class="small muted">${desc}</p><div class="row">${btn('▷ Listen',null,'pill listen')}${btn('Explore the guide ↗',go,'text-btn')}</div>`);
const search=placeholder=>`<label class="search"><span>⌕</span><input type="search" aria-label="${placeholder}" placeholder="${placeholder}"></label>`;
const moods=()=>`<div class="moods">${['☺|Joyful','◡|Calm','◯|Okay','☂|Low','〰|Anxious'].map((x,i)=>{const [a,b]=x.split('|');return `<button class="${i===1?'selected':''}" data-select aria-label="${b}">${a}<small>${b}</small></button>`}).join('')}</div>`;
const nav=(active='home')=>`<nav class="bottom-nav" aria-label="App navigation">${[['home','Home','02'],['practice','Practice','03'],['journal','Journal','20'],['growth','Growth','22']].map(([a,b,c])=>`<button data-go="${c}" class="${active===a?'selected':''}">${icon[a]}<span>${b}</span></button>`).join('')}</nav>`;
const player=()=>`<div class="player">${btn('↺',null,'circle reset')}${btn('▶',null,'play playback')}${btn('↻',null,'circle reset')}</div>`;
const orb=(label='Breathe in',count='4')=>`<div class="breath-orb"><small>${label}</small><strong>${count}</strong><small>Let this moment be enough</small></div>`;
const progress=(a='1:24',b='5:00')=>`<div class="progress"></div><div class="row micro"><span>${a}</span><span>${b}</span></div>`;
const toggle=(label,sub='',checked=true)=>`<label class="switch-row"><span>${label}<small>${sub}</small></span><input type="checkbox" class="toggle" aria-label="${label}" ${checked?'checked':''}></label>`;
const days=()=>`<div class="days">${['F|6','S|7','S|8','M|9','T|10','W|11','T|12'].map((d,i)=>`<button data-select class="${i===6?'selected':''}"><small>${d.split('|')[0]}</small>${d.split('|')[1]}</button>`).join('')}</div>`;
const tiles=(arr)=>`<div class="grid2">${arr.map(([symbol,title,sub,to])=>`<button class="tile" data-go="${to||'05'}"><span class="symbol">${symbol}</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div>`;
const areas=[['✧','Wealth & money','Create room for abundance','07'],['❧','Health & body','A kinder connection','07'],['♡','Love & romance','Open your heart','07'],['∞','Relationships','Connection & boundaries','07'],['⌂','Family','Love, roots & belonging','07'],['▱','Career & work','Purpose in the everyday','07'],['☼','Confidence','Trust your own voice','07'],['〰','Emotional wellbeing','Make space for your feelings','07']];
const practices=[['✧','Affirmations','Words to grow with','05'],['☝','EFT tapping','Release with a gentle touch','11'],['♫','Sound healing','Find your frequency','15'],['❀',"Ho’oponopono",'A practice of forgiveness','18'],['〰','Breathwork','Come back to your breath','25'],['☼','Chakra guide','Explore your inner energy','27']];
const chakras=[['Crown','Sahasrara','I know','#ab8dbb'],['Third eye','Ajna','I see','#8990c3'],['Throat','Vishuddha','I speak','#88b6c4'],['Heart','Anahata','I love','#8fae97'],['Solar plexus','Manipura','I do','#d2b36f'],['Sacral','Svadhisthana','I feel','#d59e7e'],['Root','Muladhara','I am','#c68891']];
const chakraRows=(reverse=false,expanded=false)=>`<div class="card chakras">${(reverse?[...chakras].reverse():chakras).map(([n,s,w,c],i)=>`<div class="list-item"><span class="chakra-dot" style="--chakra:${c}">✳</span><div class="detail"><strong>${n}</strong><small>${s}</small></div>${btn(w+' ↗',expanded?'28':'08','text-btn')}</div>`).join('')}</div>`;
const bodymap=`<svg class="body-map" viewBox="0 0 190 230" role="img" aria-label="Tap gently at the beginning of your eyebrow, beside the bridge of your nose"><path d="M42 228V155Q44 128 73 120V102Q49 82 56 44Q61 11 94 10Q129 11 134 45Q141 80 116 102V120Q147 128 150 155V228Z" fill="#fcf3ec" stroke="#9783ab" stroke-width="2"/><path d="M56 49Q72 25 96 28Q122 28 134 49M72 65Q79 60 86 65M105 65Q113 60 119 65M95 68L91 86H99M84 96Q96 103 108 96M72 135Q94 143 119 135" fill="none" stroke="#9783ab" stroke-width="2" stroke-linecap="round"/><circle cx="85" cy="60" r="15" fill="#ebbad1" opacity=".5"/><circle cx="85" cy="60" r="5" fill="#c686ab"/><path d="M85 60L28 51" stroke="#c686ab" stroke-dasharray="3 3"/><circle cx="23" cy="50" r="12" fill="#fff"/><text x="23" y="54" text-anchor="middle" font-size="11" fill="#826890">2</text></svg>`;
const screens=[];
function add(id,title,group,body,opts={}){screens.push({id,title,group,body,...opts})}
add('01','Welcome & language','Essentials',`<div class="center"><div class="kicker">YOUR SPACE TO SIMPLY BE</div><h3>A softer place<br>to <em>begin.</em></h3><p class="subtitle small">Small moments of care.<br>A deeper connection to yourself.</p></div><div class="welcome-bottom"><div class="card language"><div class="row"><strong class="small">Make yourself at home</strong><span class="micro">Language</span></div>${pills(['English','हिन्दी','Русский','한국어','中文','Español','Français','Italiano','日本語'])}</div>${primary('Begin your journey','02')}<p class="quiet-note">♧ Private by nature. No account needed.</p></div>`,{theme:'welcome',noNav:true,wordmark:true});
add('02','Your sanctuary','Essentials',`<div class="row"><span class="kicker">THURSDAY, NOVEMBER 12</span><span class="pill">☼ Evening</span></div><h3>Come as you are.</h3><p class="muted small">A little care can change your day.</p><div class="hero"><div class="kicker">YOUR DAILY PAUSE</div><h4>Let yourself<br><em>gently unfold.</em></h4><span class="pill">✧ 5-minute practice</span>${btn('▶','26','play')}</div><div class="calm-strip" data-go="29"><span class="symbol">〰</span><span>Need a moment of calm?<small>Let’s take one breath together.</small></span><span>↗</span></div>${heading('How are you arriving?')}${moods()}${heading('Words for today','Open card','08')}${card('<div class="kicker">HEART · I LOVE</div><h4>I am worthy of the care<br>I give to others.</h4>','affirm')}` ,{wordmark:true});
add('03','Explore your practices','Essentials',`<div class="kicker">YOUR EVERYDAY SANCTUARY</div><h3>A practice for<br>every version of you.</h3>${search('Find a practice')}${tiles(practices)}${heading('Make space for yourself')}${card(item('▤','A page of your own','Journal, reflect, begin again','20')+item('◷','Little steps, lasting care','Build your personal rituals','22'))}${card('<h4>Mantra Mala</h4><p class="small muted">Explore your companion for chanting and japa.</p>'+btn('About this companion ↗','34','text-btn'))}`,{active:'practice'});
add('04','Practice menu','Essentials',`<div class="kicker">INNER LOTUS</div><h3>Your own<br>little sanctuary.</h3>${card(practices.map(([a,b,c,d])=>item(a,b,c,d)).join(''))}${card(item('⚙','Settings','Make this space yours','31')+item('♡','About Inner Lotus','Made with care','34'))}<p class="quiet-note">♧ Your practice stays with you, on this device.</p>`,{noNav:true});
add('05','Affirmation life areas','Affirmations',`<h3>Words to grow into.</h3><p class="muted small">Choose the part of your life that needs a little kindness.</p>${info('A gentler inner voice','A few intentional words. A moment of attention. An invitation to see yourself with kindness.')}${search('Search 33 life areas')}${tiles(areas.slice(0,4))}`,{bar:'Affirmations',active:'practice'});
add('06','More life areas','Affirmations',`${search('Search 33 life areas')}${pills(['All areas','Saved','My affirmations'])}${tiles([...areas.slice(4),['✦','Self-love','You are already enough','07'],['☾','Spirituality','Reconnect with meaning','07'],['↗','Personal growth','Become at your own pace','07'],['❋','Creativity','Make space to imagine','07']])}`,{bar:'Affirmations',active:'practice'});
add('07','Choose a chakra','Affirmations',`<div class="kicker">WEALTH & MONEY</div><h3>Where would you<br>like to begin?</h3><p class="muted small">Choose an energy centre, or let a word find you.</p>${btn('✧ Choose for me <span>↗</span>','08','primary secondary')}<div style="height:15px"></div>${chakraRows()}<p class="quiet-note">7 chakras · 1,008 affirmations in this area</p>`,{bar:'Your intention',noNav:true});
add('08','Affirmation player','Affirmations',`${segments(['All · 144','My words','Favourites'])}<div class="card affirm" style="height:380px;padding-top:45px"><div class="kicker" style="color:#769780">HEART CHAKRA</div><h3 style="color:#6b9276;font-size:20px;letter-spacing:3px">I LOVE</h3><p class="quote" style="margin:30px 0">Money flows to me<br>easily and often.</p><p style="font:italic 17px Georgia;color:#7c927f">I am worthy of love.</p><div class="micro" style="margin-top:40px">WEALTH & MONEY · 01 / 144</div></div>${player()}${segments(['Tap to play','Autoplay','Repeat ×3'])}<div class="row">${btn('♡ Save',null,'pill favourite')}${btn('＋ My words','09','pill')}${btn('↗ Export','10','pill')}</div>`,{bar:'Wealth & money',noNav:true});
add('09','Write affirmations','Affirmations',`<div class="kicker">A VOICE THAT SOUNDS LIKE YOU</div><h3>Your words.<br>Your becoming.</h3><p class="small muted">Write one affirmation per line. Use the present tense and words that feel true to you.</p>${card('<span class="pill">✧ Wealth & money</span><label><p class="small">My affirmations</p><textarea style="height:255px" placeholder="I welcome new possibilities.&#10;I can grow at my own pace."></textarea></label><p class="micro">Only you can see these words.</p>')}${btn('Save my affirmations <span>✓</span>',null,'primary save')}<div class="row" style="margin-top:14px">${btn('Import','10','pill')}${btn('Export','10','pill')}${btn('Clear draft',null,'pill clear')}</div>`,{bar:'My affirmations',noNav:true});
add('10','Import & export','Affirmations',`<h3>Keep your words<br>close.</h3><p class="small muted">Make a copy of your practice, or bring your saved affirmations with you.</p>${card('<span class="symbol">▤</span><h4>Your personal collection</h4><p class="small muted">My affirmations & favourites<br>Includes your custom cards and saved words.</p>'+btn('Export collection ↓',null,'primary export')+'<div style="height:9px"></div>'+btn('Import a backup ↑',null,'primary secondary import'))}${card('<h4>One area at a time</h4><p class="small muted">Choose a section to save as a spreadsheet.</p><select aria-label="Area" style="width:100%;padding:12px;border:1px solid #ddd2e5;border-radius:14px"><option>Wealth & money</option><option>Self-love</option><option>Health & body</option></select>'+pills(['All chakras','Heart'])+btn('Export selected area ↓',null,'primary secondary export'))}${card('<h4>The whole library</h4><p class="small muted">All 33 areas, ready to take with you.</p>'+btn('Export library ↓',null,'pill export'))}`,{bar:'Import & export',noNav:true});
add('11','EFT techniques','Practices',`<h3>A gentle touch.<br>A little release.</h3>${info('Meet EFT tapping','Pair gentle fingertip tapping with words that acknowledge how you feel. Move at your own pace.')}${heading('Choose your practice')}${card(item('◌','Basic recipe','A simple, guided starting point · 5 min','12')+item('✧','Full recipe + 9 Gamut','A longer practice with extra steps · 8 min','12')+item('〰','Gentle touch & breathe','A quiet, wordless pause · 3 min','12')+item('☼','Positive round','Make room for encouragement · 4 min','12'))}<p class="quiet-note">Tap gently. You can pause or stop at any time.</p>`,{bar:'EFT tapping',active:'practice'});
add('12','EFT topics','Practices',`<div class="kicker">BASIC RECIPE · 5 MINUTES</div><h3>What’s on your<br>heart today?</h3><p class="small muted">There’s no wrong way to feel.</p>${tiles([['〰','Anxiety','Find a little steadiness','13'],['≈','Overwhelm','Take one thing at a time','13'],['☁','Sadness','Make room for tenderness','13'],['✴','Frustration','Soften what feels tight','13'],['◌','Fear','Return to the present','13'],['♡','Not enough','Meet yourself with care','13'],['☾','Restless nights','Set down your day','13'],['∞','Relationship hurt','A moment for your heart','13']])}`,{bar:'Choose a feeling',noNav:true});
add('13','Before tapping check-in','Practices',`<div class="read-progress"><i class="done"></i><i></i><i></i><i></i></div><div class="kicker">BEFORE WE BEGIN</div><h3>Let’s meet you<br>where you are.</h3><p class="small muted">How strong does the anxiety feel right now?</p><div class="breath-orb"><small>Your feeling, from 0 to 10</small><strong class="rating-value">7</strong><small>Every feeling is welcome</small></div>${card('<input class="range intensity" type="range" min="0" max="10" value="7" aria-label="Feeling intensity"><div class="row micro"><span>Calm · 0</span><span>Very intense · 10</span></div>')}${primary('Begin tapping','14')}<p class="quiet-note">You can return to your breath whenever you need.</p>`,{bar:'A gentle check-in',noNav:true,theme:'rose'});
add('14','Guided tapping session','Practices',`<div class="read-progress"><i class="done"></i><i class="done"></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="center"><div class="kicker">POINT 02 OF 08</div><h3>Eyebrow</h3><p class="small muted">At the beginning of your brow,<br>beside the bridge of your nose.</p></div>${bodymap}${card('<div class="kicker center">TAP GENTLY 5–7 TIMES AND SAY</div><p class="quote">“This tightness<br>in my chest.”</p>')}${player()}${btn('Next tapping point <span>→</span>',null,'primary tap-next')}`,{bar:'Releasing anxiety',noNav:true});
add('15','Healing frequencies','Practices',`<h3>Find your quiet.</h3><p class="small muted">A little sound. A little space.</p>${info('Listen, soften, settle','Explore steady tones and natural sound as companions for rest and mindful attention.') }<div class="segments">${btn('Frequencies','15','selected')}${btn('Soundscapes','16')}${btn('My mixes','17')}</div>${card([['174 Hz','A grounded beginning'],['285 Hz','A moment to renew'],['396 Hz','Room to let go'],['417 Hz','Welcome a new chapter'],['528 Hz','A softer connection']].map(([a,b])=>`<div class="list-item"><span class="badge">∿</span><div class="detail"><strong>${a}</strong><small>${b}</small></div>${btn('▶',null,'play playback')}</div>`).join(''))}<p class="quiet-note">Listen at a comfortable volume.</p>`,{bar:'Sound healing',active:'practice'});
add('16','Nature soundscapes','Practices',`<h3>A place to exhale.</h3><p class="small muted">Layer sounds to make this moment your own.</p><div class="segments">${btn('Frequencies','15')}${btn('Soundscapes','16','selected')}${btn('My mixes','17')}</div><div class="grid2">${[['☂','Soft rain'],['≈','Ocean waves'],['❧','Forest stream'],['〰','Evening wind'],['♧','Birdsong'],['♨','Warm fire']].map(([s,t],i)=>`<button class="tile sound ${i===0?'selected':''}" aria-pressed="${i===0}"><span class="symbol">${s}</span><strong>${t}</strong><small>${i===0?'Playing · tap to mute':'Tap to add a layer'}</small></button>`).join('')}</div>${heading('Your soundscape')}${card('<div class="row"><span class="small">☂ Soft rain</span><span class="micro">65%</span></div><input class="range" type="range" value="65" aria-label="Rain volume">')}${primary('Save as a mix','17')}`,{bar:'Sound healing',active:'practice',theme:'mint'});
add('17','Saved sound mixes','Practices',`<h3>Your kind of calm.</h3><div class="segments">${btn('Frequencies','15')}${btn('Soundscapes','16')}${btn('My mixes','17','selected')}</div>${heading('Made by you')}${card('<span class="symbol">♫</span><h4>A soundscape of your own</h4><p class="small muted">Blend the sounds you love and save them here.</p>'+btn('＋ Create a mix','16','pill'))}${heading('Ready when you are')}${card(item('☂','Rainy temple','Rain · Temple bell','16','▶')+item('❧','Himalayan morning','Forest stream · Birdsong · Singing bowl','16','▶')+item('☾','Deep sleep','Brown noise · Soft rain','16','▶')+item('≈','Ocean meditation','Ocean waves · Crystal bowl','16','▶'))}`,{bar:'Sound healing',active:'practice'});
add('18','Forgiveness intention','Practices',`<div class="kicker">HO’OPONOPONO</div><h3>Make room<br>for forgiveness.</h3>${card('<p class="quote">I’m sorry. Please forgive me.<br><em>Thank you. I love you.</em></p>','tint')}<p class="small muted">Choose an intention for this personal reflection.</p>${pills(['Myself','My partner','My parents','My children','A friendship','Work & career','My body','The past','My home','Someone else'])}${card('<h4>A moment, repeated</h4><div class="row"><span class="small muted">Repeat the four phrases</span><div class="row">'+btn('−',null,'circle minus')+'<strong class="repeat-count">3</strong>'+btn('+',null,'circle plus')+'</div></div>')}<p class="small muted">Let the words be an invitation. There’s no need to force a feeling.</p>${primary('Begin your reflection','19')}`,{bar:'Forgiveness',noNav:true});
add('19','Forgiveness prayer','Practices',`<div class="kicker center">A PRACTICE OF SOFTENING</div><h3 class="center">Back to love.</h3><p class="center small muted">For myself · 3 gentle rounds</p>${card('<p class="small muted">I bring myself into this moment, just as I am. I make space for what I am ready to release.</p><p class="quote" style="line-height:2;margin:25px 0">I’m sorry.<br>Please forgive me.<br><em>Thank you.<br>I love you.</em></p><p class="small muted">May I meet myself with kindness.<br>May I begin again, in peace.</p>')}${progress('0:42','3:00')}${player()}${btn('✎ Personalise your words',null,'primary secondary edit-prayer')}<p class="quiet-note">A personal reflection inspired by the practice.<br>Use words that feel right for you.</p>`,{bar:'Your reflection',noNav:true});
add('20','Journal overview','Journal & Growth',`<div class="kicker">A SPACE THAT’S ONLY YOURS</div><h3>Leave a little<br>of your day here.</h3><p class="small muted">No perfect words. Just honest ones.</p>${tiles([['✎','Free writing','Let it all flow','21'],['✧','Gratitude','Notice the little good','21']])}${card('<div class="kicker">A PROMPT FOR TODAY</div><h4>What felt like a small<br>act of care today?</h4>'+btn('Write about this ↗','21','text-btn'),'tint')}${search('Search your journal')}${segments(['Day','Week','Month'])}${heading('Your recent pages','New entry','21')}${card('<div class="row"><span class="micro">TODAY · 8:42 AM</span><span class="pill">◡ Calm</span></div><h4 style="margin-top:13px">The quiet things</h4><p class="small muted">Sunlight on the windowsill. A warm cup of tea. Remembering to slow down…</p>'+btn('Open entry ↗','21','text-btn'))}<p class="quiet-note">♧ Private, and saved only on your device.</p>`,{bar:'Your journal',active:'journal'});
add('21','Gratitude entry','Journal & Growth',`<div class="row"><span class="kicker">THURSDAY, NOVEMBER 12</span><span class="micro">♧ Just for you</span></div><h3>There was good<br>in today.</h3><p class="small muted">Three little things. They don’t have to be big.</p>${['Something that made you smile','Someone you’re grateful for','Something you appreciate about yourself'].map((s,i)=>card(`<label><span class="kicker">0${i+1} · ${s}</span><textarea style="min-height:65px;margin-top:9px" placeholder="Let your words land here…"></textarea></label>`)).join('')}<h4>How do you feel?</h4>${moods()}${btn('Save this moment <span>✓</span>',null,'primary save')}`,{bar:'Gratitude',noNav:true});
add('22','Daily rituals','Journal & Growth',`<div class="kicker">GROW AT YOUR OWN PACE</div><h3>Small steps.<br>More of you.</h3>${days()}${card('<div class="row"><div><span class="kicker">TODAY’S LITTLE WINS</span><div class="stat habit-count">2 <span class="muted" style="font-size:18px">/ 4</span></div></div><span style="font-size:35px;color:#9a80ae">◔</span></div><p class="small muted">Every moment of care counts.</p>','tint')}${card(['A mindful minute','Drink a glass of water','Write a few honest words','Step outside'].map((s,i)=>`<label class="list-item"><span class="badge">${['〰','♧','✎','☼'][i]}</span><span class="detail"><strong>${s}</strong><small>${['A little pause for yourself','A refreshing reset','Your journal is waiting','Find a little fresh air'][i]}</small></span><input type="checkbox" class="check habit-check" ${i<2?'checked':''} aria-label="${s}"></label>`).join(''))}${primary('＋ Add a ritual','23')}${heading('Your journey','View insights ↗','24')}`,{bar:'Daily rituals',active:'growth'});
add('23','Add a ritual','Journal & Growth',`<h3>Small steps.<br>More of you.</h3>${days()}${card('<h4>Your daily rituals</h4><p class="small muted">A little care, every day.</p>')}`,{bar:'Daily rituals',active:'growth',overlay:`<div class="modal-veil"></div><div class="sheet"><div class="handle"></div><div class="row"><h3>A little promise<br>to yourself.</h3>${btn('×','22','circle')}</div><p class="small muted">Choose something kind, and keep it simple.</p><label class="small">Ritual name<input type="text" id="ritualName" placeholder="e.g. Take a mindful minute" style="margin:9px 0 16px"></label><div class="kicker">A FEW GENTLE IDEAS</div>${pills(['Meditate','Drink water','Read a page','Gratitude','Walk outdoors','Breathwork','Sleep routine','Call someone'], -1)}<div class="kicker">MAKE IT YOURS</div>${pills(['✧','〰','☼','♧','♡'])}${btn('Add to my day <span>＋</span>',null,'primary add-habit')}<p class="quiet-note">Consistency can be gentle, too.</p></div>`});
add('24','Your progress','Journal & Growth',`<div class="kicker">YOUR JOURNEY, WITH KINDNESS</div><h3>Look how you’re<br>showing up.</h3>${segments(['7 days','30 days','All time'])}<div class="grid2">${card('<div class="kicker">THIS WEEK</div><div class="stat">71<span style="font-size:17px">%</span></div><span class="small muted">Rituals completed</span>')}${card('<div class="kicker">STEADY MOMENTS</div><div class="stat">5<span style="font-size:17px"> days</span></div><span class="small muted">Longest streak</span>')}</div>${heading('A week of little wins')}${card('<div class="bars">'+[45,70,90,52,75,100,50].map((h,i)=>`<div class="bar-col"><div class="bar" style="height:${h}px"></div><span>${['F','S','S','M','T','W','T'][i]}</span></div>`).join('')+'</div><p class="micro">Completed rituals · last 7 days</p>')}${heading('Your rhythm, over time')}${card('<div class="micro">LAST 12 WEEKS</div><div class="heatmap">'+'<i></i>'.repeat(84)+'</div><p class="micro">Less ░ ▒ ▓ More</p>')}<p class="quiet-note">Progress has pauses. They belong here, too.</p>`,{bar:'Your growth',active:'growth'});
add('25','Breathwork library','Practices',`<h3>Come back<br>to your breath.</h3><p class="small muted">One breath is a place to begin.</p>${card('<div class="kicker">SETTLE IN</div><h4>How much time is yours?</h4>'+pills(['1 min','3 min','5 min','10 min','15 min'],1)+toggle('Spoken guidance','A gentle voice to guide you'))}${heading('Find your rhythm')}${card(item('□','Box breathing','4 in · 4 hold · 4 out · 4 hold','26','▶')+item('☾','4–7–8 breathing','A slower rhythm for winding down','26','▶')+item('∞','Coherent breathing','An even, easy pace','26','▶'))}${card('<p class="small muted">Keep your breath comfortable. If you feel lightheaded, pause and breathe normally.</p>','sage')}`,{bar:'Breathwork',active:'practice',theme:'mint'});
add('26','Breathing session','Practices',`<div class="center"><div class="kicker">A MOMENT TO RETURN</div><h3><em>Box breathing</em></h3><p class="small muted">Soften your shoulders. Let the day settle.</p></div>${orb()}<div class="center micro">INHALE · HOLD · EXHALE · HOLD</div>${progress('0:24','3:00')}${player()}${card('<div class="row"><span class="mini-art"></span><div style="flex:1"><strong class="small">Your quiet companion</strong><div class="micro">Soft rain · low volume</div></div>'+btn('♫','16','circle')+'</div>')}<p class="quiet-note">Let your breath stay easy.<br>You can pause whenever you need.</p>`,{bar:'Just breathe',noNav:true,theme:'rose'});
add('27','Chakra guide','Practices',`<div class="kicker">A MAP FOR REFLECTION</div><h3>Explore your<br>inner landscape.</h3><p class="small muted">Meet the seven energy centres described in yogic traditions.</p>${chakraRows(true,true)}<p class="quiet-note">An invitation to explore, at your own pace.</p>`,{bar:'Chakra guide',active:'practice'});
add('28','Chakra detail','Practices',`<div class="center"><div class="chakra-dot" style="--chakra:#8fae97;width:88px;height:88px;font-size:48px;margin:20px auto">✳</div><div class="kicker">ANAHATA · THE FOURTH CHAKRA</div><h3>The heart.</h3><p style="color:#6c9475;letter-spacing:3px">I LOVE</p></div>${card('<h4>A place for connection</h4><p class="small muted">In yogic traditions, the heart chakra is associated with love, compassion and connection. It invites us to reflect on how we give and receive care.</p>','sage')}${heading('A gentle practice')}${card('<p class="small muted">Place a hand over your heart. Take a comfortable breath. Offer yourself the kindness you would offer a friend.</p><p class="quote">“I am worthy of love,<br>just as I am.”</p>')}${primary('Explore heart affirmations','08')}`,{bar:'Heart chakra',noNav:true,theme:'mint'});
add('29','Calm now breathing','Care & Settings',`<div class="center"><div class="kicker">RIGHT HERE. RIGHT NOW.</div><h3>Let’s slow down<br><em>together.</em></h3><p class="small muted">Nothing to solve in this moment.<br>Just one gentle breath.</p></div>${orb('Breathe out','6')}${player()}<p class="quiet-note">Breathe in for 4. Breathe out for 6.<br>Or follow your own comfortable rhythm.</p>${btn('Find my feet · grounding <span>→</span>','30','primary secondary')}<p class="quiet-note">You can stop whenever you need to.</p>`,{bar:'A moment of calm',noNav:true,theme:'rose'});
add('30','Grounding & support','Care & Settings',`<div class="kicker">COME BACK TO THE PRESENT</div><h3>One thing<br>at a time.</h3>${card([['5','Things you can see'],['4','Things you can feel'],['3','Sounds you can hear'],['2','Things you can smell'],['1','Thing you can taste']].map(([n,t])=>`<div class="list-item"><span class="badge">${n}</span><strong style="font-size:12px;font-weight:400">${t}</strong></div>`).join(''))}${card('<p class="quote" style="font-size:18px">“I can take this<br>one moment at a time.”</p>'+btn('▷ Hear these words',null,'pill listen'))}<div class="grid2">${btn('Gentle tapping','11','pill')}${btn('Soothing sounds','16','pill')}</div>${heading('Need more support?')}${card('<p class="small muted">If you are in immediate danger or may hurt yourself, contact local emergency services or someone you trust.</p><a class="pill" href="https://findahelpline.com" target="_blank" rel="noopener">Find a local helpline ↗</a>')}`,{bar:'Grounding',noNav:true});
add('31','Language & voice','Care & Settings',`<h3>Make it feel<br>like you.</h3><div class="settings-label">LANGUAGE</div>${card(pills(['English','हिन्दी','Русский','한국어','中文','Español','Français','Italiano','日本語']))}<div class="settings-label">YOUR LISTENING EXPERIENCE</div>${card('<h4>A voice for your practice</h4><p class="small muted">Use your device’s installed voices.</p><label class="small">Speaking speed <span class="muted">· 0.9×</span><input class="range" type="range" min="50" max="150" value="90" aria-label="Speaking speed"></label><label class="small">Voice pitch <span class="muted">· 1.0</span><input class="range" type="range" min="50" max="150" value="100" aria-label="Voice pitch"></label>'+toggle('Read chakra statements')+btn('▷ Try this voice',null,'pill listen'))}${card(item('◐','Appearance','Colours, backgrounds & card style','32')+item('♧','Privacy & reminders','Your space, your preferences','33'))}`,{bar:'Settings',noNav:true});
add('32','Appearance & backgrounds','Care & Settings',`<div class="kicker">SET THE MOOD</div><h3>Your sanctuary,<br>your palette.</h3><p class="small muted">Choose a backdrop that helps you feel at home.</p><div class="themes">${['Petal','Meadow','Sky','Dawn','Dusk','Lotus'].map((x,i)=>`<button class="theme-thumb ${i===0?'selected':''}" data-select aria-label="${x} background"><span class="pill">${x}</span></button>`).join('')}</div>${card('<h4>A little variety</h4>'+segments(['One backdrop','Gentle rotation'])+toggle('Shuffle affirmation cards','A fresh order within each chakra'))}${heading('A preview of your space')}${card('<div class="kicker">A MOMENT FOR YOU</div><h4>There is no rush<br>to become.</h4><p class="small muted">You can begin right where you are.</p>','affirm')}${btn('Use this appearance <span>✓</span>',null,'primary save')}`,{bar:'Appearance',noNav:true});
add('33','Privacy & reminders','Care & Settings',`<h3>A space<br>you can trust.</h3><div class="settings-label">GENTLE REMINDERS</div>${card(toggle('Daily affirmation','Every morning · 08:00',false)+toggle('A moment to journal','Every evening · 21:00',false))}<div class="settings-label">PRIVACY & COMFORT</div>${card('<div class="switch-row"><span>Journal PIN lock<small>Add a little extra privacy</small></span>'+btn('Set PIN',null,'pill pin')+'</div>'+toggle('Keep screen awake','During your guided sessions'))}${card('<span class="symbol">♧</span><h4>Your inner world stays yours.</h4><p class="small muted">Inner Lotus is designed to work offline, without accounts, advertising or tracking. Your journal, rituals and personal words stay on your device.</p><p class="small muted">You choose when to export or share. Make a backup before uninstalling the app.</p>','sage')}${btn('Manage backups ↗','10','primary secondary')}`,{bar:'Privacy & reminders',noNav:true});
add('34','About Inner Lotus','Care & Settings',`<div class="center" style="margin:18px 0 25px"><img class="lotus-logo" src="assets/logo.png" alt="Inner Lotus logo"><h3 style="margin-top:20px">Inner Lotus</h3><p class="small muted">A little space to return to yourself.</p><span class="pill">Made with care by Sj Pixels</span></div><div class="hero" style="height:180px;background-position:center 77%"></div>${card('<h4>Care, at your own pace.</h4><p class="small muted">Affirmations, gentle tapping, sound, breath and reflection. Small practices to accompany your everyday life.</p><p class="small muted">No account. No audience. Just you, and a moment that belongs to you.</p>')}<p class="quiet-note">Inner Lotus is a self-care and wellness companion.<br>It does not provide medical care or replace professional support.</p><p class="quiet-note">DESIGN EDITION · 01</p>`,{bar:'About',noNav:true});
add('35','Learning article','Care & Settings',`<div class="kicker">THE INNER LOTUS GUIDE · 3 MIN READ</div><h3>A gentler way<br>to speak to yourself.</h3><div class="row" style="margin:18px 0">${btn('▷ Listen to this guide',null,'pill listen')}${btn('♡',null,'circle favourite')}</div><div class="card affirm" style="min-height:160px"><h4>“I can meet this day<br>with kindness.”</h4></div><div class="text-page"><h4>What is an affirmation?</h4><p>An affirmation is a short, intentional statement you return to. Think of it as a gentle prompt for your attention, rather than a promise that everything will change.</p><h4>Start with something believable.</h4><p>Choose words that feel supportive and possible. “I am learning to trust myself” may feel more natural than a statement you don’t yet believe.</p><h4>Make a little room for it.</h4><p>Read your words slowly. Take a comfortable breath. Notice what comes up, without trying to force a particular feeling.</p><h4>Let your practice be yours.</h4><p>You can change the words, skip a card or come back another day. A small act of kindness is enough.</p></div>${primary('Find your words','05')}`,{bar:'A kinder inner voice',noNav:true});
function renderPhone(s){return `<article class="phone ${s.theme||''} ${s.noNav?'no-nav':''}" data-screen="${s.id}" aria-label="${s.title}"><div class="status"><span>9:41</span><i class="island"></i><b>▮▮▮ ▰</b></div><div class="topbar">${s.wordmark?'<span class="wordmark">✳ inner lotus</span>':btn('‹',s.id==='02'?'01':'02','circle')} ${s.wordmark?'':`<h2>${s.bar||s.title}</h2>`}${btn(s.wordmark?'⚙':'···',s.wordmark?'31':'04','circle')}</div><div class="content">${s.body}</div>${s.noNav?'':nav(s.active)}${s.overlay||''}<div class="home-indicator"></div></article>`}
let current=1;const groups=['All screens','Essentials','Affirmations','Practices','Journal & Growth','Care & Settings'];
const gallery=document.querySelector('#gallery');
function renderGallery(group='All screens'){gallery.innerHTML=screens.filter(s=>group==='All screens'||s.group===group).map(s=>`<section class="screen-wrap"><div class="screen-label"><span>${s.id} / ${s.title}</span><button data-open="${s.id}">Explore ↗</button></div>${renderPhone(s)}</section>`).join('')}
document.querySelector('#filters').innerHTML=groups.map((g,i)=>`<button class="${i===0?'active':''}" data-filter="${g}">${g}</button>`).join('');
document.querySelector('#screenSelect').innerHTML=screens.map(s=>`<option value="${s.id}">${s.id} · ${s.title}</option>`).join('');
function openScreen(id){const s=screens.find(x=>x.id===String(id).padStart(2,'0'));if(!s)return;current=screens.indexOf(s);document.querySelector('#prototype').hidden=false;document.querySelector('#prototype').scrollTop=0;document.querySelector('#stage').innerHTML=renderPhone(s);document.querySelector('#screenSelect').value=s.id;document.body.style.overflow='hidden'}
function close(){document.querySelector('#prototype').hidden=true;document.body.style.overflow='';window.speechSynthesis?.cancel()}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),2800)}
document.querySelector('#mode').onclick=()=>openScreen('02');document.querySelector('#close').onclick=close;document.querySelector('#screenSelect').onchange=e=>openScreen(e.target.value);document.querySelector('#previous').onclick=()=>openScreen(screens[(current+34)%35].id);document.querySelector('#next').onclick=()=>openScreen(screens[(current+1)%35].id);
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(document.querySelector('#prototype').hidden||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')document.querySelector('#next').click();if(e.key==='ArrowLeft')document.querySelector('#previous').click()});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-go]');if(!b)return;const phone=b.closest('.phone');if(b.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderGallery(b.dataset.filter)}if(b.dataset.open)openScreen(b.dataset.open);if(b.dataset.go)openScreen(b.dataset.go);if(b.hasAttribute('data-select')){b.parentElement.querySelectorAll('[data-select]').forEach(x=>x.classList.toggle('selected',x===b));if(phone?.dataset.screen==='23'&&b.closest('.pills')===phone.querySelector('.sheet .pills'))phone.querySelector('#ritualName').value=b.textContent}if(b.classList.contains('favourite')){b.classList.toggle('selected');b.textContent=b.classList.contains('selected')?'♥ Saved':'♡ Save'}if(b.classList.contains('save'))toast('Saved for this design preview');if(b.classList.contains('clear')){phone.querySelectorAll('textarea').forEach(t=>t.value='');toast('Draft cleared')}if(b.classList.contains('playback')){const playing=b.textContent==='Ⅱ';b.textContent=playing?'▶':'Ⅱ';phone?.querySelector('.breath-orb')?.classList.toggle('breathe-active',!playing);if(!phone?.querySelector('.breath-orb'))toast('Player state preview · audio is not included')}if(b.classList.contains('reset')){phone.querySelectorAll('.playback').forEach(x=>x.textContent='▶');phone.querySelector('.breath-orb')?.classList.remove('breathe-active')}if(b.classList.contains('sound')){b.classList.toggle('selected');b.setAttribute('aria-pressed',b.classList.contains('selected'));b.querySelector('small').textContent=b.classList.contains('selected')?'Added to preview mix':'Tap to add a layer';toast('Sound layer preview · audio is not included')}if(b.classList.contains('plus')||b.classList.contains('minus')){const n=phone.querySelector('.repeat-count');n.textContent=Math.max(1,Math.min(20,Number(n.textContent)+(b.classList.contains('plus')?1:-1)))}if(b.classList.contains('add-habit')){const name=phone.querySelector('#ritualName').value.trim();if(!name){toast('Give your ritual a name first');return}openScreen('22');const content=document.querySelector('#stage .content');const label=document.createElement('label');label.className='list-item';const text=document.createElement('span');text.className='detail';text.textContent=name;const check=document.createElement('input');check.type='checkbox';check.className='check habit-check';label.append(text,check);content.querySelectorAll('.card')[1].append(label);updateHabits(document.querySelector('#stage .phone'));toast('Ritual added to this preview')}if(b.classList.contains('listen')){speechSynthesis.cancel();const text=phone.querySelector('.content').innerText;const utterance=new SpeechSynthesisUtterance(text);utterance.rate=.9;speechSynthesis.speak(utterance);toast('Reading aloud · Escape to stop')}if(b.classList.contains('export')||b.classList.contains('import'))toast('Design preview · connect to the app’s data storage');if(b.classList.contains('pin'))toast('Design preview · PIN setup requires the app’s secure storage');if(b.classList.contains('edit-prayer')){const quote=phone.querySelector('.quote');quote.contentEditable=quote.contentEditable!=='true';quote.focus();toast('You can edit the reflection in this preview')}if(b.classList.contains('tap-next')){const n=Number(phone.dataset.point||2);const next=n%8+1;phone.dataset.point=next;phone.querySelector('.center .kicker').textContent=`POINT ${String(next).padStart(2,'0')} OF 08`;phone.querySelector('.center h3').textContent=['Karate chop','Eyebrow','Side of eye','Under eye','Under nose','Chin','Collarbone','Under arm'][next-1];phone.querySelector('.center p').textContent='Continue with gentle tapping at your own pace.';phone.querySelector('.body-map').style.opacity='.25';toast('Next-step layout preview · illustration shows eyebrow point')}});
function updateHabits(phone){const all=[...phone.querySelectorAll('.habit-check')];phone.querySelector('.habit-count').innerHTML=`${all.filter(x=>x.checked).length} <span class="muted" style="font-size:18px">/ ${all.length}</span>`}
document.addEventListener('input',e=>{const phone=e.target.closest('.phone');if(e.target.classList.contains('intensity'))phone.querySelector('.rating-value').textContent=e.target.value;if(e.target.type==='search'){const q=e.target.value.toLowerCase();phone.querySelectorAll('.tile').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q))}});document.addEventListener('change',e=>{if(e.target.classList.contains('habit-check'))updateHabits(e.target.closest('.phone'))});renderGallery();
